const assert = require('assert');
const { resolveSession } = require('/workspace/src/session.js');

(async () => {
  // 1. Same context+session is cached, and returns the same object.
  {
    let calls = 0;
    const io = { tenantId: 'A', async loadSession(id) { calls++; return { id }; } };
    const a = await resolveSession(io, 's1');
    const b = await resolveSession(io, 's1');
    assert.strictEqual(calls, 1, 'expected one load, got ' + calls);
    assert.strictEqual(a, b);
  }

  // 2. Different sessions cached independently.
  {
    let calls = 0;
    const io = { tenantId: 'A', async loadSession(id) { calls++; return { id }; } };
    await resolveSession(io, 's1');
    await resolveSession(io, 's2');
    await resolveSession(io, 's1');
    assert.strictEqual(calls, 2);
  }

  // 3. Same shared context, different tenants must not collide.
  {
    let calls = 0;
    const io = { tenantId: 'A', async loadSession(id) { calls++; return { tenant: io.tenantId, id }; } };
    const a = await resolveSession(io, 's1');
    io.tenantId = 'B';
    const b = await resolveSession(io, 's1');
    assert.strictEqual(calls, 2, 'cross-tenant collision');
    assert.deepStrictEqual(a, { tenant: 'A', id: 's1' });
    assert.deepStrictEqual(b, { tenant: 'B', id: 's1' });
  }

  // 4. Separate contexts with same sessionId are isolated.
  {
    const a = await resolveSession({ tenantId: 'A', async loadSession: async () => ({ t: 'A' }) }, 's1');
    const b = await resolveSession({ tenantId: 'B', async loadSession: async () => ({ t: 'B' }) }, 's1');
    assert.deepStrictEqual(a, { t: 'A' });
    assert.deepStrictEqual(b, { t: 'B' });
  }

  // 5. Concurrent misses coalesce into one load.
  {
    let calls = 0;
    const io = { tenantId: 'A', async loadSession(id) { calls++; await new Promise(r => setTimeout(r, 20)); return { id }; } };
    const [a, b, c] = await Promise.all([
      resolveSession(io, 's1'), resolveSession(io, 's1'), resolveSession(io, 's1'),
    ]);
    assert.strictEqual(calls, 1, 'expected coalesced load, got ' + calls);
    assert.strictEqual(a, b);
    assert.strictEqual(b, c);
  }

  // 6. Failures are not cached; retry works.
  {
    let calls = 0;
    const io = { tenantId: 'A', async loadSession(id) {
      calls++;
      if (calls === 1) throw new Error('boom');
      return { id };
    } };
    await assert.rejects(() => resolveSession(io, 's1'));
    const s = await resolveSession(io, 's1');
    assert.deepStrictEqual(s, { id: 's1' });
    assert.strictEqual(calls, 2);
  }

  // 7. Frozen context still caches (WeakMap fallback).
  {
    let calls = 0;
    const io = Object.freeze({ tenantId: 'A', async loadSession(id) { calls++; return { id }; } });
    await resolveSession(io, 's1');
    await resolveSession(io, 's1');
    assert.strictEqual(calls, 1);
  }

  // 8. Alternate tenant shapes.
  for (const io of [
    { tenant: { id: 'T' } },
    { tenant: 'T' },
    { ctx: { tenantId: 'T' } },
    { context: { tenantId: 'T' } },
    { tenant_id: 'T' },
  ]) {
    let calls = 0;
    io.loadSession = async (id) => { calls++; return { id }; };
    await resolveSession(io, 'x');
    await resolveSession(io, 'x');
    assert.strictEqual(calls, 1, 'no cache for ' + JSON.stringify(io));
  }

  console.log('all assertions passed');
})().catch((e) => { console.error(e); process.exit(1); });
EOF
